// Streaming archive reader built on libarchive.
//
// The archive is never copied into wasm memory and there is no filesystem layer: libarchive pulls
// bytes through read/seek/skip callbacks from a JS "source" object (ArchiveSource below):
//
//   { size: number, read(offset: number, length: number): Uint8Array | null }
//
// Results are plain C++ structs registered with embind's value_object, so the TypeScript types in
// dist/extract.d.ts are generated by Emscripten (--emit-tsd) rather than written by hand.
//
// In a browser worker `read` slices the user's File with FileReaderSync; in Node it uses
// fs.readSync. Peak wasm memory is one read block plus the entry being extracted, whatever the
// archive size, which is what makes archives over 2 GB (and over 4 GB) work.
//
// The seek callback matters: with it libarchive uses its seekable zip reader, which reads the
// central directory once and jumps between entries, so listing a multi-GB zip reads a few MB.

#include <archive.h>
#include <archive_entry.h>
#include <emscripten/bind.h>
#include <emscripten/heap.h>
#include <emscripten/val.h>

#include <algorithm>
#include <cerrno>
#include <cstdint>
#include <cstdio>
#include <optional>
#include <string>
#include <vector>

using emscripten::val;

// JS values with a specific TypeScript shape (see register_type below).
EMSCRIPTEN_DECLARE_VAL_TYPE(ArchiveSource);
EMSCRIPTEN_DECLARE_VAL_TYPE(Uint8Array);
// A JS string. A plain std::string field would be typed `EmbindString` (string | ArrayBuffer |
// Uint8Array | ...) in the generated TypeScript, because value objects are also accepted as input;
// these fields are output-only, so they are typed as `string`.
EMSCRIPTEN_DECLARE_VAL_TYPE(JsString);

JsString js_string(const std::string& text) {
  return JsString(val(text));
}

struct ArchiveEntry {
  JsString path{val::undefined()};
  bool is_file = false;
  // Uncompressed size in bytes, or -1 when the archive does not record it up front.
  double size = -1;
};

// Exactly one of the fields is set.
struct OpenResult {
  std::optional<uintptr_t> handle;
  std::optional<JsString> error;
};

// `entry` is set for the next entry, `error` on failure, and neither at the end of the archive.
struct NextEntryResult {
  std::optional<ArchiveEntry> entry;
  std::optional<JsString> error;
};

// Exactly one of the fields is set. `data` is owned by JS: there is nothing to free.
struct ReadEntryResult {
  std::optional<Uint8Array> data;
  std::optional<JsString> error;
};

namespace {

// Larger blocks mean fewer JS round trips; smaller blocks mean less wasted reading when the zip
// reader jumps between entries. 256 KiB measured well for both.
constexpr size_t READ_BLOCK_SIZE = 256 * 1024;

struct Reader {
  archive* arch = nullptr;
  ArchiveSource source = ArchiveSource(val::undefined());
  int64_t size = 0;
  int64_t position = 0;
  std::vector<uint8_t> block = std::vector<uint8_t>(READ_BLOCK_SIZE);
  int64_t current_entry_size = -1;
};

Reader* to_reader(uintptr_t handle) {
  return reinterpret_cast<Reader*>(handle);
}

JsString error_of(archive* arch, const char* fallback) {
  const char* message = archive_error_string(arch);
  return js_string(message ? message : fallback);
}


la_ssize_t read_callback(archive* arch, void* client_data, const void** buffer) {
  auto* reader = static_cast<Reader*>(client_data);
  *buffer = reader->block.data();

  const int64_t remaining = reader->size - reader->position;
  if (remaining <= 0) {
    return 0;
  }

  const auto wanted = static_cast<size_t>(std::min<int64_t>(remaining, reader->block.size()));
  // Positions are passed as doubles: exact up to 2^53 bytes (8 PiB).
  val chunk = reader->source.call<val>("read", static_cast<double>(reader->position), static_cast<double>(wanted));
  if (chunk.isNull() || chunk.isUndefined()) {
    archive_set_error(arch, EIO, "could not read the archive file");
    return ARCHIVE_FATAL;
  }

  const size_t got = std::min(chunk["length"].as<size_t>(), wanted);
  if (got == 0) {
    archive_set_error(arch, EIO, "the archive file ended early");
    return ARCHIVE_FATAL;
  }

  // One copy, straight from the JS buffer into wasm memory.
  val(emscripten::typed_memory_view(got, reader->block.data()))
      .call<void>("set", got == chunk["length"].as<size_t>() ? chunk : chunk.call<val>("subarray", 0, got));
  reader->position += static_cast<int64_t>(got);
  return static_cast<la_ssize_t>(got);
}

la_int64_t seek_callback(archive*, void* client_data, la_int64_t offset, int whence) {
  auto* reader = static_cast<Reader*>(client_data);
  int64_t target = offset;
  if (whence == SEEK_CUR) {
    target += reader->position;
  } else if (whence == SEEK_END) {
    target += reader->size;
  }

  if (target < 0) {
    return ARCHIVE_FATAL;
  }

  reader->position = target;
  return target;
}

la_int64_t skip_callback(archive*, void* client_data, la_int64_t request) {
  auto* reader = static_cast<Reader*>(client_data);
  const int64_t skipped = std::max<int64_t>(0, std::min<int64_t>(request, reader->size - reader->position));
  reader->position += skipped;
  return skipped;
}

}  // namespace

// Opens an archive. `source.read` must not throw: return null if the data cannot be read.
OpenResult open_archive(ArchiveSource source) {
  auto* reader = new Reader();
  reader->source = source;
  reader->size = static_cast<int64_t>(source["size"].as<double>());
  reader->arch = archive_read_new();

  archive* arch = reader->arch;
  archive_read_support_filter_all(arch);
  archive_read_support_format_zip(arch);
  archive_read_support_format_rar(arch);
  archive_read_support_format_rar5(arch);

  archive_read_set_callback_data(arch, reader);
  archive_read_set_read_callback(arch, read_callback);
  archive_read_set_seek_callback(arch, seek_callback);
  archive_read_set_skip_callback(arch, skip_callback);

  OpenResult result;
  if (archive_read_open1(arch) != ARCHIVE_OK) {
    result.error = error_of(arch, "could not open archive");
    archive_read_free(arch);
    delete reader;
    return result;
  }

  result.handle = reinterpret_cast<uintptr_t>(reader);
  return result;
}

void close_archive(uintptr_t handle) {
  Reader* reader = to_reader(handle);
  if (reader == nullptr) {
    return;
  }

  archive_read_free(reader->arch);
  delete reader;
}

// Advances to the next entry.
NextEntryResult next_entry(uintptr_t handle) {
  Reader* reader = to_reader(handle);
  archive_entry* entry = nullptr;
  NextEntryResult result;

  const int status = archive_read_next_header(reader->arch, &entry);
  if (status == ARCHIVE_EOF) {
    return result;
  }

  if (status < ARCHIVE_WARN) {
    result.error = error_of(reader->arch, "could not read entry header");
    return result;
  }

  reader->current_entry_size = archive_entry_size_is_set(entry) ? archive_entry_size(entry) : -1;

  const char* utf8_path = archive_entry_pathname_utf8(entry);
  const char* raw_path = archive_entry_pathname(entry);

  result.entry = ArchiveEntry{
      .path = js_string(utf8_path ? utf8_path : (raw_path ? raw_path : "")),
      .is_file = archive_entry_filetype(entry) == AE_IFREG,
      .size = static_cast<double>(reader->current_entry_size),
  };
  return result;
}

// Reads the whole current entry into a new JS Uint8Array.
ReadEntryResult read_entry(uintptr_t handle) {
  Reader* reader = to_reader(handle);
  ReadEntryResult result;
  std::vector<uint8_t> data;
  if (reader->current_entry_size > 0) {
    data.reserve(static_cast<size_t>(reader->current_entry_size));
  }

  // Heap, not stack: Emscripten's default stack is only 64 KiB.
  std::vector<uint8_t> block(64 * 1024);

  for (;;) {
    const la_ssize_t read = archive_read_data(reader->arch, block.data(), block.size());
    if (read == 0) {
      break;
    }

    if (read < 0) {
      result.error = error_of(reader->arch, "could not read entry data");
      return result;
    }

    data.insert(data.end(), block.begin(), block.begin() + read);
  }

  // Copy out of wasm memory into a JS-owned array before `data` is freed.
  result.data = Uint8Array(val::global("Uint8Array").new_(emscripten::typed_memory_view(data.size(), data.data())));
  return result;
}

// Skips the current entry's data without extracting it.
bool skip_entry(uintptr_t handle) {
  Reader* reader = to_reader(handle);
  return archive_read_data_skip(reader->arch) == ARCHIVE_OK;
}

// Current size of the wasm heap, for memory diagnostics.
double memory_bytes() {
  return static_cast<double>(emscripten_get_heap_size());
}

std::string libarchive_version() {
  return archive_version_details();
}

EMSCRIPTEN_BINDINGS(extract) {
  using namespace emscripten;

  register_type<ArchiveSource>(
      "ArchiveSource",
      "{ readonly size: number; read(offset: number, length: number): Uint8Array | null }");
  register_type<Uint8Array>("Uint8Array");
  register_type<JsString>("string");

  value_object<ArchiveEntry>("ArchiveEntry")
      .field("path", &ArchiveEntry::path)
      .field("isFile", &ArchiveEntry::is_file)
      .field("size", &ArchiveEntry::size);

  value_object<OpenResult>("OpenResult")
      .field("handle", &OpenResult::handle)
      .field("error", &OpenResult::error);

  value_object<NextEntryResult>("NextEntryResult")
      .field("entry", &NextEntryResult::entry)
      .field("error", &NextEntryResult::error);

  value_object<ReadEntryResult>("ReadEntryResult")
      .field("data", &ReadEntryResult::data)
      .field("error", &ReadEntryResult::error);

  register_optional<uintptr_t>();
  register_optional<JsString>();
  register_optional<ArchiveEntry>();
  register_optional<Uint8Array>();

  function("open_archive", &open_archive);
  function("close_archive", &close_archive);
  function("next_entry", &next_entry);
  function("read_entry", &read_entry);
  function("skip_entry", &skip_entry);
  function("libarchive_version", &libarchive_version);
  function("memory_bytes", &memory_bytes);
}
